WITH upsert AS ( UPDATE dcr30_link
                    SET dcr30_class_tree_id = ( SELECT dcr01_class_tree_id
                                                  FROM dcr01_class_tree
                                                 WHERE dcr01_company_id = #{companyId}
                                                   AND dcr01_insert_bak_dcr_id = #{classTreeId} ),
                        dcr30_note = #{note}
                  WHERE dcr30_company_id = #{companyId}
                    AND dcr30_link_cd    = #{linkCode}
              RETURNING * )
INSERT INTO dcr30_link
SELECT f_create_seq(),
       #{linkCode},
       ( SELECT dcr01_class_tree_id
           FROM dcr01_class_tree
          WHERE dcr01_company_id = #{companyId}
            AND dcr01_insert_bak_dcr_id = #{classTreeId} ),
       #{companyId},
       #{formMappingId},
       #{note}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

